def parents_for(child_ids, child_to_parent, max_parents):
    out = []
    for c in child_ids:
        p = child_to_parent.get(c)
        if p is None or p in out:
            continue
        out.append(p)
        if len(out) == max_parents:
            break
    return out

def citation_problems(claims, retrieved_ids):
    problems = []
    for claim in claims:
        if not claim['citations']:
            problems.append('uncited: ' + claim['text'][:20])
        for cid in claim['citations']:
            if cid not in retrieved_ids:
                problems.append('unretrieved: ' + cid)
    return problems

