coding.solution:
def crag_action(scores, upper=0.7, lower=0.3):
    if any(s >= upper for s in scores):
        return 'use'
    if not scores or all(s < lower for s in scores):
        return 'fallback'
    return 'refine'

def run_with_retry(search, grade, query, rewrite, max_tries=2):
    for attempt in range(max_tries):
        docs = search(query)
        action = crag_action(grade(docs))
        if action != 'fallback':
            return action, docs
        query = rewrite(query)
    return 'abstain', []
